package com.rulecraft.decisionops.decisionapi;
import static org.assertj.core.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import com.rulecraft.decisionops.catalog.CatalogService;import com.rulecraft.decisionops.catalog.CatalogService.*;import com.rulecraft.decisionops.catalog.domain.*;import com.rulecraft.decisionops.decisionapi.ApiCredentialService.*;import com.rulecraft.decisionops.deployment.RuntimeDeploymentService;import com.rulecraft.decisionops.deployment.RuntimeDeploymentService.DeployCommand;import com.rulecraft.decisionops.expressions.DecisionExpressionService;import com.rulecraft.decisionops.expressions.DecisionExpressionService.ExpressionCommand;import com.rulecraft.decisionops.graph.DecisionGraphService;import com.rulecraft.decisionops.graph.DecisionGraphService.*;import com.rulecraft.decisionops.graph.domain.*;import com.rulecraft.decisionops.identity.persistence.UserAccountRepository;import com.rulecraft.decisionops.identity.security.RuleCraftPrincipal;import com.rulecraft.decisionops.projects.ProjectService;import com.rulecraft.decisionops.versions.DecisionVersionService;import com.rulecraft.decisionops.versions.DecisionVersionService.CaptureCommand;import com.rulecraft.decisionops.workflow.ApprovalWorkflowService;import com.rulecraft.decisionops.workflow.ApprovalWorkflowService.*;import java.time.Clock;import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.http.MediaType;import org.springframework.test.web.servlet.MockMvc;import tools.jackson.databind.*;
@SpringBootTest @AutoConfigureMockMvc class DecisionApiIntegrationTest {@Autowired MockMvc mvc;@Autowired ApiCredentialService credentials;@Autowired RuntimeDeploymentService deployment;@Autowired ApprovalWorkflowService workflow;@Autowired DecisionVersionService versions;@Autowired DecisionExpressionService expressions;@Autowired DecisionGraphService graphs;@Autowired CatalogService catalog;@Autowired ProjectService projects;@Autowired UserAccountRepository users;@Autowired ObjectMapper mapper;@Autowired Clock clock;RuleCraftPrincipal admin;@BeforeEach void actor(){admin=new RuleCraftPrincipal(users.findForLogin("acme-rules","admin@example.test").orElseThrow(),"acme-rules");}
@Test void authenticatesPinsAndIdempotentlyEvaluatesSingleRequests()throws Exception{var fixture=fixture();activate(fixture);var created=credentials.create(admin,fixture.projectId(),fixture.serviceId(),new CreateCredential("Production client"));var requestId=UUID.randomUUID();var body=json(Map.of("requestId",requestId,"inputs",Map.of("score",710)));var first=mvc.perform(post(url(fixture,"evaluate")).header("Authorization","Bearer "+created.secret()).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isOk()).andExpect(jsonPath("$.outputs.approved").value(true)).andExpect(jsonPath("$.decisionVersionId").isNotEmpty()).andExpect(jsonPath("$.artifactFingerprint").isNotEmpty()).andReturn().getResponse().getContentAsString();var second=mvc.perform(post(url(fixture,"evaluate")).header("Authorization","Bearer "+created.secret()).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();assertThat(second).isEqualTo(first);mvc.perform(post(url(fixture,"evaluate")).header("Authorization","Bearer "+created.secret()).contentType(MediaType.APPLICATION_JSON).content(json(Map.of("requestId",requestId,"inputs",Map.of("score",699))))).andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("RC-API-REQUEST-CONFLICT"));mvc.perform(post("/api/runtime/v1/decisions/WRONG/evaluate").header("Authorization","Bearer "+created.secret()).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isNotFound()).andExpect(jsonPath("$.code").value("RC-API-SERVICE-NOT-FOUND"));}
@Test void convergesConcurrentFirstUseRetriesOnOneDurableResponse()throws Exception{var fixture=fixture();activate(fixture);var created=credentials.create(admin,fixture.projectId(),fixture.serviceId(),new CreateCredential("Concurrent client"));var body=json(Map.of("requestId",UUID.randomUUID(),"inputs",Map.of("score",710)));var executor=Executors.newFixedThreadPool(4);var ready=new CountDownLatch(4);var start=new CountDownLatch(1);try{var calls=new ArrayList<Future<String>>();for(int index=0;index<4;index++)calls.add(executor.submit(()->{ready.countDown();start.await();return mvc.perform(post(url(fixture,"evaluate")).header("Authorization","Bearer "+created.secret()).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();}));assertThat(ready.await(10,TimeUnit.SECONDS)).isTrue();start.countDown();var responses=new HashSet<String>();for(var call:calls)responses.add(call.get(30,TimeUnit.SECONDS));assertThat(responses).hasSize(1);}finally{executor.shutdownNow();}}
@Test void returnsOrderedPartialBatchEvidenceAndRejectsInvalidOrRevokedKeys()throws Exception{var fixture=fixture();activate(fixture);var created=credentials.create(admin,fixture.projectId(),fixture.serviceId(),new CreateCredential("Batch client"));var requestId=UUID.randomUUID();var body=json(Map.of("requestId",requestId,"items",List.of(Map.of("correlationId","eligible","inputs",Map.of("score",710)),Map.of("correlationId","missing","inputs",Map.of()),Map.of("correlationId","declined","inputs",Map.of("score",650)))));mvc.perform(post(url(fixture,"batch")).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isUnauthorized()).andExpect(jsonPath("$.code").value("RC-API-KEY-INVALID"));var response=mvc.perform(post(url(fixture,"batch")).header("Authorization","Bearer "+created.secret()).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("PARTIAL")).andExpect(jsonPath("$.succeededCount").value(2)).andExpect(jsonPath("$.failedCount").value(1)).andExpect(jsonPath("$.items[0].correlationId").value("eligible")).andExpect(jsonPath("$.items[1].errorCode").value("RC-DEPLOY-INPUT-MISSING")).andReturn().getResponse().getContentAsString();assertThat(mvc.perform(post(url(fixture,"batch")).header("Authorization","Bearer "+created.secret()).contentType(MediaType.APPLICATION_JSON).content(body)).andReturn().getResponse().getContentAsString()).isEqualTo(response);credentials.revoke(admin,fixture.projectId(),fixture.serviceId(),created.credential().id(),new RevokeCredential(created.credential().version()));mvc.perform(post(url(fixture,"batch")).header("Authorization","Bearer "+created.secret()).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isUnauthorized()).andExpect(jsonPath("$.code").value("RC-API-KEY-INVALID"));}
@Test void publishesVersionedRuntimeContractsAndBearerScheme()throws Exception{mvc.perform(get("/v3/api-docs")).andExpect(status().isOk()).andExpect(jsonPath("$.paths['/api/runtime/v1/decisions/{serviceKey}/evaluate']").exists()).andExpect(jsonPath("$.paths['/api/runtime/v1/decisions/{serviceKey}/batch']").exists()).andExpect(jsonPath("$.components.securitySchemes.decisionApiKey.scheme").value("bearer"));}private String url(Fixture fixture,String action){return "/api/runtime/v1/decisions/"+fixture.serviceKey()+"/"+action;}private String json(Object value)throws Exception{return mapper.writeValueAsString(value);}private void activate(Fixture fixture){var state=versions.working(admin,fixture.projectId(),fixture.serviceId());var version=versions.capture(admin,fixture.projectId(),fixture.serviceId(),new CaptureCommand(UUID.randomUUID(),"API baseline","Decision API candidate",state.serviceVersion(),state.graphVersion(),state.fingerprint()));var request=workflow.create(admin,fixture.projectId(),fixture.serviceId(),new CreateCommand(UUID.randomUUID(),version.id(),"Approve API baseline",null));var submitted=workflow.submit(admin,fixture.projectId(),fixture.serviceId(),request.id(),new TransitionCommand(UUID.randomUUID(),request.version(),null));var approved=workflow.approve(admin,fixture.projectId(),fixture.serviceId(),request.id(),new TransitionCommand(UUID.randomUUID(),submitted.version(),null));workflow.promote(admin,fixture.projectId(),fixture.serviceId(),request.id(),new TransitionCommand(UUID.randomUUID(),approved.version(),null));var promotion=workflow.workflow(admin,fixture.projectId(),fixture.serviceId()).promotion();deployment.deploy(admin,fixture.projectId(),fixture.serviceId(),new DeployCommand(UUID.randomUUID(),version.id(),promotion.revision()));}private Fixture fixture(){var project=projects.create(admin,key("D"),"Decision API",null);var service=catalog.createService(admin,project.id(),new DecisionServiceCommand(key("API"),"API eligibility",null,List.of(new FieldCommand("score","Score",builtin(BuiltinType.NUMBER),true)),List.of(new FieldCommand("approved","Approved",builtin(BuiltinType.BOOLEAN),true)),null));var graph=graphs.initialize(admin,project.id(),service.id());var nodeId=UUID.randomUUID();var input=port(GraphPortDirection.INPUT,"score",BuiltinType.NUMBER);var output=port(GraphPortDirection.OUTPUT,"approved",BuiltinType.BOOLEAN);var serviceInput=graph.nodes().stream().filter(node->node.kind()==GraphNodeKind.INPUT).findFirst().orElseThrow().ports().getFirst();var serviceOutput=graph.nodes().stream().filter(node->node.kind()==GraphNodeKind.OUTPUT).findFirst().orElseThrow().ports().getFirst();var nodes=new ArrayList<NodeCommand>();graph.nodes().forEach(node->nodes.add(command(node)));nodes.add(new NodeCommand(nodeId,"threshold","Approval threshold",GraphNodeKind.DECISION,null,300,100,List.of(input,output)));graphs.update(admin,project.id(),service.id(),new GraphCommand(graph.version(),nodes,List.of(edge(serviceInput.id(),input.id()),edge(output.id(),serviceOutput.id()))));var expression=expressions.initialize(admin,project.id(),service.id(),nodeId);expressions.update(admin,project.id(),service.id(),nodeId,new ExpressionCommand(expression.version(),"score >= 700"));return new Fixture(project.id(),service.id(),service.serviceKey());}private CatalogService.TypeRefCommand builtin(BuiltinType type){return new CatalogService.TypeRefCommand(type,null);}private PortCommand port(GraphPortDirection direction,String key,BuiltinType type){return new PortCommand(UUID.randomUUID(),direction,key,key,new DecisionGraphService.TypeRefCommand(type,null),true,0);}private NodeCommand command(GraphNodeView node){return new NodeCommand(node.id(),node.nodeKey(),node.name(),node.kind(),node.serviceFieldKey(),node.positionX(),node.positionY(),node.ports().stream().map(port->new PortCommand(port.id(),port.direction(),port.portKey(),port.label(),port.type(),port.required(),port.position())).toList());}private EdgeCommand edge(UUID source,UUID target){return new EdgeCommand(UUID.randomUUID(),source,target);}private String key(String prefix){return prefix+UUID.randomUUID().toString().replace("-","").substring(0,8).toUpperCase();}private record Fixture(UUID projectId,UUID serviceId,String serviceKey){}
}
